from .events import RULES, utc_iso

PROVENANCE_NOTE = {
    "live_capture": "observed on a live capture interface",
    "simulation": "SYNTHETIC: generated by the built-in simulator, not observed traffic",
    "synthetic_test": "SYNTHETIC: test fixture",
    "historical": "recorded by an earlier version of BlockAudit; fewer evidence fields were kept",
    "integrity_monitor": "raised by the ledger integrity monitor",
    "operator": "recorded by an operator action",
}


def missing_evidence(alert, block, packets):
    gaps = []
    ev = alert.get("evidence") or {}
    if not ev.get("sample_packets") and not packets:
        gaps.append("no packet samples are available; they were not recorded or have rolled out of memory")
    if not ev.get("thresholds") and alert["type"] != "INTEGRITY":
        gaps.append("the thresholds that triggered the detection were not recorded")
    if alert.get("ledger_index") is None:
        gaps.append("this alert is not recorded in the audit ledger, so its integrity cannot be checked")
    elif block is None:
        gaps.append("the ledger block for this alert could not be read")
    if ev.get("legacy"):
        gaps.append("recorded by an earlier version: packet samples, thresholds and exact timestamps are unavailable")
    if alert["type"] == "ANOMALY":
        gaps.append("an anomaly score alone does not establish malicious activity")
    return gaps


def build_report(alert, related, block, block_check, investigation, health_status):
    meta = RULES.get(alert["type"], {})
    return {
        "generated_at": utc_iso(),
        "title": f"{meta.get('title', alert['type'])}: {alert['id']}",
        "alert": {k: alert.get(k) for k in (
            "id", "timestamp", "last_seen", "occurrences", "type", "severity", "source", "destination", "dst_port",
            "protocol", "rule", "score", "score_kind", "description", "status", "provenance")},
        "provenance_note": PROVENANCE_NOTE.get(alert["provenance"], alert["provenance"]),
        "why_flagged": meta.get("explains"),
        "evidence": alert.get("evidence") or {},
        "related_alerts": [{k: r[k] for k in ("id", "timestamp", "type", "severity", "relation")} for r in related],
        "ledger": {"index": alert.get("ledger_index"), "hash": alert.get("ledger_hash"),
                   "block": block, "verification": block_check},
        "investigation": {"status": investigation["status"], "notes": investigation["notes"]},
        "recommended_next_steps": meta.get("next_steps", []),
        "known_false_positives": meta.get("false_positives"),
        "missing_evidence": missing_evidence(alert, block, alert.get("evidence", {}).get("sample_packets")),
        "system_health_at_generation": health_status,
        "limitations": "scores are uncalibrated heuristics; payloads are not captured; the ledger is a local hash chain "
                       "and does not protect against an attacker who can rewrite both the ledger and its checkpoint",
    }


def to_markdown(r):
    a = r["alert"]
    L = [f"# {r['title']}", "", f"generated {r['generated_at']}  ", f"data provenance: {r['provenance_note']}", "",
         "## summary", "", f"- severity: {a['severity']}", f"- type: {a['type']} (rule {a['rule']})",
         f"- first seen: {a['timestamp']}  last seen: {a['last_seen']}  occurrences: {a['occurrences']}",
         f"- source: {a['source'] or 'n/a'}  destination: {a['destination'] or 'n/a'}"
         f"{':' + str(a['dst_port']) if a['dst_port'] else ''}",
         f"- status: {a['status']}"]
    if a["score"] is not None:
        L.append(f"- {a['score_kind']}: {a['score']} (uncalibrated, not a probability)")
    L += ["", a["description"], "", "## why it was flagged", "", r["why_flagged"] or "no explanation available", "",
          "## evidence", ""]
    ev = r["evidence"]
    for k, v in (ev.get("observed") or {}).items():
        L.append(f"- observed {k}: {v}")
    for k, v in (ev.get("thresholds") or {}).items():
        L.append(f"- threshold {k}: {v}")
    samples = ev.get("sample_packets") or []
    if samples:
        L += ["", "| time | src | dst | proto | size | flags |", "|---|---|---|---|---|---|"]
        L += [f"| {s['time']} | {s['src']}:{s['sport']} | {s['dst']}:{s['dport']} | {s['proto']} | {s['size']} | {s['flags']} |"
              for s in samples]
    L += ["", "## related alerts", ""]
    L += [f"- {x['timestamp']} {x['severity']} {x['type']} ({x['relation']}) {x['id']}" for x in r["related_alerts"]] or ["none found"]
    lg = r["ledger"]
    L += ["", "## audit ledger", ""]
    if lg["index"] is None:
        L.append("not recorded in the ledger")
    else:
        L += [f"- block {lg['index']}  hash {lg['hash']}"]
        v = lg["verification"]
        if v:
            L.append(f"- chain verification at generation: {'passed' if v['valid'] else 'FAILED'} - {v['message']}")
    L += ["", "## investigation", "", f"status: {r['investigation']['status']}"]
    L += [f"- {n['at']} {n['by']}: {n['text']}" for n in r["investigation"]["notes"]]
    L += ["", "## recommended next steps", ""] + [f"- {s}" for s in r["recommended_next_steps"]]
    if r["known_false_positives"]:
        L += ["", f"common false positives: {r['known_false_positives']}"]
    L += ["", "## missing evidence", ""] + ([f"- {g}" for g in r["missing_evidence"]] or ["none identified"])
    L += ["", "## limitations", "", r["limitations"], ""]
    return "\n".join(L)
